<?php
declare(strict_types=1);define('_JEXEC',1);define('JPATH_BASE','/var/www/html');require_once JPATH_BASE.'/includes/defines.php';require_once JPATH_BASE.'/includes/framework.php';
use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;
$c=Factory::getContainer();$c->alias('session','session.cli')->alias('JSession','session.cli')->alias(Joomla\CMS\Session\Session::class,'session.cli')->alias(Joomla\Session\Session::class,'session.cli')->alias(Joomla\Session\SessionInterface::class,'session.cli');Factory::$application=$c->get(Joomla\Console\Application::class);$db=$c->get(DatabaseInterface::class);
$rows=$db->setQuery($db->getQuery(true)->select(['match.id','match.scheduled_start','result.id AS result_id','result.finalized_at'])->from($db->quoteName('#__joomleague_project_match','match'))->innerJoin($db->quoteName('#__joomleague_match_result','result')." ON result.match_id=match.id AND result.status_code='final'")->where("match.scheduled_start>='2035-01-01'"))->loadObjectList();$changed=0;
foreach($rows as$row){$match=(object)['id'=>(int)$row->id,'scheduled_start'=>(new DateTimeImmutable((string)$row->scheduled_start))->modify('-10 years')->format('Y-m-d H:i:s'),'status_code'=>'finished'];$db->updateObject('#__joomleague_project_match',$match,'id');if($row->finalized_at!==null){$result=(object)['id'=>(int)$row->result_id,'finalized_at'=>(new DateTimeImmutable((string)$row->finalized_at))->modify('-10 years')->format('Y-m-d H:i:s')];$db->updateObject('#__joomleague_match_result',$result,'id');}$events=$db->setQuery($db->getQuery(true)->select(['id','occurred_at'])->from($db->quoteName('#__joomleague_match_event'))->where('match_id='.(int)$row->id)->where("occurred_at>='2035-01-01'"))->loadObjectList();foreach($events as$event){$update=(object)['id'=>(int)$event->id,'occurred_at'=>(new DateTimeImmutable((string)$event->occurred_at))->modify('-10 years')->format('Y-m-d H:i:s')];$db->updateObject('#__joomleague_match_event',$update,'id');}$changed++;}
